fn_src.renderFileContentToPdf:
function renderFileContentToPdf(base64) {
    var app = important_data.is_mobile;
    if (app == "Y") {
        mobileScriptChannel.postMessage(
            "openFile:" + "data:application/pdf," + base64
        );
    } else {
        let binaryData = atob(base64);

        let byteArray = new Uint8Array(binaryData.length);

        for (let i = 0; i < binaryData.length; i++) {
            byteArray[i] = binaryData.charCodeAt(i);
        }
        const mimeType = "application/pdf";

        const blob = new Blob([byteArray], { type: mimeType });

        let downloadUrl = URL.createObjectURL(blob);

        window.open(downloadUrl, "_blank");
    }
}

