            url: url_GenerateTemplateAppeal,
            data: {
                group_Id: group_Id,
                form_Id: form_Id,
                form_Seq: form_Seq,
            },

            success: function (data, textStatus, jqXHR) {
                var response = JSON.parse(data);

                renderFileContentToPdf(response.data);

                //   hide_loading();

                $("#loading").hide();
            },
            error: function (error) {
